from django.conf import settings
settings.configure(INSTALLED_APPS=['django.contrib.contenttypes'],DATABASES={'default': {'ENGINE':'django.db.backends.sqlite3','NAME':':memory:'}},SECRET_KEY='x')
import django; django.setup()
from django.db import models

class Document(models.Model):
    class Meta: app_label='myapp'

# ptr first should work now.
try:
    class Picking(Document):
        document_ptr = models.OneToOneField(Document, on_delete=models.CASCADE, parent_link=True, related_name='+')
        origin = models.OneToOneField(Document, related_name='picking', on_delete=models.PROTECT)
        class Meta: app_label='myapp'
    print('Picking ok')
except Exception as e:
    print('Picking error', type(e), e)

# origin first should work
try:
    class Picking2(Document):
        origin = models.OneToOneField(Document, related_name='picking2', on_delete=models.PROTECT)
        document_ptr = models.OneToOneField(Document, on_delete=models.CASCADE, parent_link=True, related_name='+')
        class Meta: app_label='myapp'
    print('Picking2 ok')
except Exception as e:
    print('Picking2 error', type(e), e)

# missing parent_link should still error
try:
    class Child(Document):
        origin = models.OneToOneField(Document, on_delete=models.PROTECT)
        class Meta: app_label='myapp'
    print('Child ok (unexpected)')
except Exception as e:
    print('Child error (expected):', type(e), e)

